  "nordic": "/* nordic: demo brand theme. Cool paper, deep green action, tighter corners.\n   Shows how far one theme file moves every component. */\n:root {\n  --ds-bg: #EEF1F0;\n  --ds-surface: #F8FAF9;\n  --ds-panel: #E6EBE9;\n  --ds-raised: #FFFFFF;\n\n  --ds-ink: #0E1F1A;\n  --ds-text: #2B3A35;\n  --ds-muted: #6E7F79;\n  --ds-line: #CFD8D5;\n\n  --ds-action: #1F5C4A;\n  --ds-on-action: #FFFFFF;\n\n  --ds-info-fill: #E8F1F7;      --ds-info-line: #3E7CA8;\n  --ds-neutral-fill: #E6EBE9;   --ds-neutral-line: #6E7F79;\n  --ds-note-fill: #E5F3EC;      --ds-note-line: #2F9467;\n  --ds-highlight-fill: #FBF1DC; --ds-highlight-line: #D79A1E;\n  --ds-danger-fill: #F9E8E6;    --ds-danger-line: #B8432F;\n\n  --ds-series-1: #1F5C4A;\n  --ds-series-2: #3E7CA8;\n  --ds-series-3: #D79A1E;\n  --ds-series-4: #6E7F79;\n  --ds-series-5: #B8432F;\n\n  --ds-font-sans: \"Avenir Next\", Avenir, \"Segoe UI\", ui-sans-serif, system-ui, sans-serif;\n  --ds-font-display: var(--ds-font-sans);\n  --ds-font-mono: ui-monospace, \"SF Mono\", Menlo, Consolas, monospace;\n  --ds-weight-display: 700;\n  --ds-tracking-display: -0.01em;\n\n  --ds-radius-scale: 0.5;\n  color-scheme: light;\n}\n"
