   "html": "<div class=\"c-button-set\">\n  <button class=\"btn btn--filled\" type=\"button\">Filled</button>\n  <button class=\"btn btn--tonal\" type=\"button\">Tonal</button>\n  <button class=\"btn btn--elevated\" type=\"button\">Elevated</button>\n  <button class=\"btn btn--outlined\" type=\"button\">Outlined</button>\n  <button class=\"btn btn--text\" type=\"button\">Text</button>\n  <button class=\"btn btn--filled\" type=\"button\">\n    <svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" aria-hidden=\"true\"><path d=\"M8 3v10M3 8h10\"/></svg>\n    With icon\n  </button>\n  <button class=\"btn btn--filled\" type=\"button\" disabled>Disabled</button>\n</div>",
   "css": ".c-button-set {\n  display: flex;\n  flex-wrap: wrap;\n  gap: var(--ds-space-3);\n  align-items: center;\n  justify-content: center;\n  font-family: var(--ds-font-sans);\n}\n.c-button-set .btn {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--ds-space-2);\n  height: 40px;\n  padding: 0 var(--ds-space-5);\n  border: var(--ds-stroke) solid transparent;\n  border-radius: var(--ds-radius-pill);\n  font-size: var(--ds-text-sm);\n  font-weight: 600;\n  line-height: 1;\n  cursor: pointer;\n  transition: background var(--ds-dur-fast) var(--ds-ease), box-shadow var(--ds-dur-fast) var(--ds-ease), transform var(--ds-dur-fast) var(--ds-ease);\n}\n.c-button-set .btn:active { transform: translateY(1px); }\n.c-button-set .btn:focus-visible { outline: none; box-shadow: var(--ds-focus); }\n.c-button-set .btn svg { width: 16px; height: 16px; }\n\n.c-button-set .btn--filled { background: var(--ds-action); color: var(--ds-on-action); }\n.c-button-set .btn--filled:hover { background: color-mix(in srgb, var(--ds-action) 86%, var(--ds-on-action)); }\n\n.c-button-set .btn--tonal { background: var(--ds-info-fill); color: var(--ds-ink); border-color: color-mix(in srgb, var(--ds-info-line) 35%, transparent); }\n.c-button-set .btn--tonal:hover { border-color: var(--ds-info-line); }\n\n.c-button-set .btn--elevated { background: var(--ds-raised); color: var(--ds-ink); box-shadow: var(--ds-shadow-md); }\n.c-button-set .btn--elevated:hover { box-shadow: var(--ds-shadow-lg); }\n\n.c-button-set .btn--outlined { background: transparent; color: var(--ds-ink); border-color: var(--ds-line); }\n.c-button-set .btn--outlined:hover { border-color: var(--ds-muted); background: var(--ds-surface); }\n\n.c-button-set .btn--text { background: transparent; color: var(--ds-ink); padding: 0 var(--ds-space-3); }\n.c-button-set .btn--text:hover { background: var(--ds-panel); }\n\n.c-button-set .btn:disabled { background: var(--ds-panel); color: var(--ds-muted); border-color: transparent; box-shadow: none; cursor: not-allowed; opacity: 0.7; }",
