   "html": "<div class=\"c-annotated-callout\">\n  <div class=\"frame\">\n    <div class=\"label\">Intake pipeline</div>\n    <div class=\"steps\">\n      <div class=\"step\">01 receive_email()</div>\n      <div class=\"step is-key\">02 classify_with_llm()</div>\n      <div class=\"step\">03 route_to_owner()</div>\n    </div>\n  </div>\n  <div class=\"note\">\n    <svg class=\"arrow\" viewBox=\"0 0 56 16\" preserveAspectRatio=\"none\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" aria-hidden=\"true\">\n      <line x1=\"56\" y1=\"8\" x2=\"2\" y2=\"8\"/><polyline points=\"9,2 2,8 9,14\"/>\n    </svg>\n    Step 02 is the only one that costs money per call. Cache it before scaling.\n  </div>\n</div>",
   "css": ".c-annotated-callout {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) 220px;\n  gap: var(--ds-space-8);\n  align-items: center;\n  padding: var(--ds-space-7);\n  background: var(--ds-surface);\n  border-radius: var(--ds-radius-xl);\n  font-family: var(--ds-font-sans);\n  color: var(--ds-text);\n}\n.c-annotated-callout .frame {\n  position: relative;\n  padding: var(--ds-space-6);\n  background: var(--ds-raised);\n  border: var(--ds-stroke) solid var(--ds-neutral-line);\n  border-radius: var(--ds-radius-lg);\n}\n.c-annotated-callout .label { color: var(--ds-muted); font-weight: 600; font-size: var(--ds-text-sm); margin-bottom: var(--ds-space-4); }\n.c-annotated-callout .steps { display: grid; gap: var(--ds-space-3); }\n.c-annotated-callout .step {\n  padding: var(--ds-space-3) var(--ds-space-4);\n  border: var(--ds-stroke) solid var(--ds-info-line);\n  background: var(--ds-info-fill);\n  border-radius: var(--ds-radius-md);\n  font-family: var(--ds-font-mono);\n  font-size: var(--ds-text-sm);\n}\n.c-annotated-callout .step.is-key { border-color: var(--ds-highlight-line); background: var(--ds-highlight-fill); }\n.c-annotated-callout .note {\n  position: relative;\n  padding: var(--ds-space-4);\n  background: var(--ds-note-fill);\n  border: var(--ds-stroke) solid var(--ds-note-line);\n  border-radius: var(--ds-radius-md);\n  font-size: var(--ds-text-sm);\n  font-weight: 700;\n  line-height: var(--ds-leading-snug);\n  color: var(--ds-ink);\n}\n.c-annotated-callout .arrow {\n  position: absolute;\n  right: 100%;\n  top: 50%;\n  width: var(--ds-space-8);\n  height: 16px;\n  margin-top: -8px;\n  color: var(--ds-note-line);\n  overflow: visible;\n}\n@media (max-width: 640px) {\n  .c-annotated-callout { grid-template-columns: 1fr; gap: var(--ds-space-5); padding: var(--ds-space-5); }\n  .c-annotated-callout .arrow { display: none; }\n}",
